class Inventory:
    def __init__(self):
        self.stock = {}

    def add(self, item, qty=1):
        if item in self.stock:
            self.stock[item] += qty
        else:
            self.stock[item] = qty

    def remove(self, item, qty=1):
        have = self.stock.get(item, 0)
        if qty > have:
            raise ValueError(f"only {have} of {item}")
        self.stock[item] = have - qty

    def report(self):
        lines = []
        for name in sorted(self.stock):
            if self.stock[name] > 0:
                lines.append(name + ": " + str(self.stock[name]))
        return lines
